// ─── MOTION VARIANTS ─────────────────────────────────────────────────────────

const springConfig = { type: "spring" as const, stiffness: 60, damping: 20 };

const slideUpVariants = {
  hidden: { y: 60, opacity: 0 },
  visible: (i: number) => ({
    y: 0,
    opacity: 1,
    transition: { ...springConfig, delay: i * 0.12 },
  }),
};

// ─── SHARED COMPONENTS ───────────────────────────────────────────────────────

function GoldDivider({ className = "" }: { className?: string }) {
  return (
    <div className={`flex items-center gap-4 ${className}`}>
      <div className="h-px bg-[#D4AF37] flex-1 opacity-50" />
      <div className="w-1.5 h-1.5 bg-[#D4AF37] rotate-45 opacity-80" />
      <div className="h-px bg-[#D4AF37] flex-1 opacity-50" />
    </div>
  );
}

function SectionLabel({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex items-center gap-3 mb-4">
      <div className="w-6 h-px bg-[#D4AF37]" />
      <span
        className="text-[10px] tracking-[0.35em] uppercase text-[#D4AF37]"
        style={{ fontFamily: "var(--font-inter, Inter, sans-serif)" }}
      >
        {children}
      </span>
    </div>
  );
}

function RevealBlock({
  children,
  delay = 0,
  className = "",
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const isInView = useInView(ref, { once: true, margin: "-80px" });

  return (
    <div ref={ref} className={`overflow-hidden ${className}`}>
      <motion.div
        initial={{ y: 80, opacity: 0 }}
        animate={isInView ? { y: 0, opacity: 1 } : { y: 80, opacity: 0 }}
        transition={{ ...springConfig, delay }}
      >
        {children}
      </motion.div>
    </div>
  );
}

// ─── NAVIGATION ──────────────────────────────────────────────────────────────

function Navigation() {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 60);
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const links = ["Services", "Experience", "Gallery", "Reviews", "Contact"];

  return (
    <motion.nav
      initial={{ y: -80, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        scrolled ? "glass py-3" : "bg-transparent py-5"
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 flex items-center justify-between">
        <Link href="/" className="flex items-center gap-3 group">
          <img 
            src="/images/main/logo.png" 
            alt="Aloha Water Sports" 
            className="w-12 h-12 rounded-full object-cover transition-transform duration-500 group-hover:scale-105"
          />
          <div>
            <div
              className="text-white text-sm font-semibold tracking-[0.15em] uppercase leading-none"
              style={{ fontFamily: "var(--font-playfair, serif)" }}
            >
              Aloha
            </div>
            <div
              className="text-[#D4AF37] text-[8px] tracking-[0.4em] uppercase leading-none mt-0.5 opacity-80"
              style={{ fontFamily: "var(--font-inter, sans-serif)" }}
            >
              Water Sports
            </div>
          </div>
        </Link>

        <div className="hidden lg:flex items-center gap-8">
          {links.map((link) => (
            <button
              key={link}
              onClick={() => {
                const el = document.getElementById(link.toLowerCase());
                el?.scrollIntoView({ behavior: "smooth" });
              }}
              className="nav-link text-[11px] tracking-[0.2em] uppercase text-white/70 hover:text-white transition-colors duration-300 cursor-pointer"
              style={{ fontFamily: "var(--font-inter, sans-serif)" }}
            >
              {link}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-4">
          <motion.a
            href="https://maps.app.goo.gl/9dbQrikWmZzPJUiV9" 
            target="_blank"
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            className="hidden lg:flex items-center gap-2 border border-[#D4AF37] text-white text-[10px] tracking-[0.25em] uppercase px-5 py-2.5 relative overflow-hidden group"
            style={{ fontFamily: "var(--font-inter, sans-serif)" }}
          >
            <span className="relative z-10">visit us</span>
          
            <motion.div
              className="absolute inset-0 bg-[#D4AF37]/10"
              initial={{ opacity: 0 }}
              whileHover={{ opacity: 1 }}
              transition={{ duration: 0.3 }}
            />
          </motion.a>

          <button
            className="lg:hidden flex flex-col gap-1.5 p-2"
            onClick={() => setMenuOpen(!menuOpen)}
            aria-label="Toggle menu"
          >
            <motion.div
              animate={menuOpen ? { rotate: 45, y: 7 } : { rotate: 0, y: 0 }}
              className="w-5 h-px bg-white"
            />
            <motion.div
              animate={menuOpen ? { opacity: 0 } : { opacity: 1 }}
              className="w-5 h-px bg-white"
            />
            <motion.div
              animate={menuOpen ? { rotate: -45, y: -7 } : { rotate: 0, y: 0 }}
              className="w-5 h-px bg-white"
            />
          </button>
        </div>
      </div>

      <AnimatePresence>
        {menuOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
            className="lg:hidden overflow-hidden glass border-t border-[#D4AF37]/20"
          >
            <div className="px-6 py-6 flex flex-col gap-4">
              {links.map((link) => (
                <button
                  key={link}
                  onClick={() => {
                    setMenuOpen(false);
                    setTimeout(() => {
                      const el = document.getElementById(link.toLowerCase());
                      el?.scrollIntoView({ behavior: "smooth" });
                    }, 300);
                  }}
                  className="text-left text-sm tracking-[0.2em] uppercase text-white/70 hover:text-white transition-colors cursor-pointer"
                  style={{ fontFamily: "var(--font-inter, sans-serif)" }}
                >
                  {link}
                </button>
              ))}
              <a 
               href="https://maps.app.goo.gl/9dbQrikWmZzPJUiV9" 
               target="_blank"
               rel="noopener noreferrer"
               className="mt-2 border border-[#D4AF37] text-white text-[10px] tracking-[0.25em] uppercase px-5 py-2.5 text-center block">
               Visit US
              </a>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.nav>
  );
}

